const S={uid:'',week:monday(day()),date:'',manager:'',view:'tasks',kind:'',status:'',range:'all',search:'',limit:50,rows:[],clientRows:[],revision:0,events:new Map(),assignments:[],managers:[],selected:'',sub:'shipment',contracts:[],scans:[],shelfPlans:[],feed:null,error:'',message:'',loaded:false,busy:false,mobile:false,brief:'',recording:false,voiceTarget:'shelf',recordBusy:false,pendingClips:[],drafts:new Map()};
